// Created: 2026-07-26

/**
 * Visual Style Nudge — UserPromptSubmit sub-hook (prompt/unified-dispatcher)
 *
 * The visual-style rule works but DECAYS. Two rule surfaces exist and they are
 * not the same mechanism: `.claude/rules/*.md` is re-surfaced by
 * instructions-loaded/priority-map every time a matching file is touched, but
 * `src/rules/visual-style.md` lives outside that directory and is reachable
 * only through a one-line CLAUDE.md pointer. It loads once at session start
 * and nothing ever re-fires it, so over a long technical exchange the model
 * drifts back to prose and the operator re-types "vis in ascii emojies" by
 * hand. Measured: 6+ manual re-asks in a single session on 2026-07-26.
 *
 * This sub-hook re-anchors the rule when a prompt asks for an answer with
 * SHAPE (status, comparison, options, "explain/show me X"). Advisory context
 * only — never blocks, never rewrites.
 *
 * Deliberately NOT once-per-session, unlike executor-route-nudge: firing once
 * would reproduce the exact decay this exists to fix. It is throttled by
 * prompt count instead, so it re-anchors periodically without becoming noise.
 *
 * Runs inside prompt/unified-dispatcher (no separate hooks.json entry), and
 * costs ZERO permanent system-prompt tokens — the cost is per-turn, only when
 * it fires, inside the dispatcher's existing 800t/turn cap.
 */

import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import type { HookContext, HookInput, HookResult } from '../types.js';
import { outputPromptContext, outputSilentSuccess } from '../lib/common.js';
import { NOOP_CTX } from '../lib/context.js';
import { getSessionStorageDir } from '../lib/paths.js';
import { safeIdentifier } from '../lib/safe-fs.js';

const HOOK_NAME = 'visual-style-nudge';

/** Re-anchor at most once per this many qualifying prompts. */
const THROTTLE_EVERY = 8;

/** Below this, the prompt is a command or a one-word answer, not a request. */
const MIN_PROMPT_LENGTH = 12;

/**
 * EXPLICIT ask: the user typed the word. This is the strongest signal that
 * exists and it is never throttled — see fireOrdinal().
 *
 * Measured on a real 13-prompt session (2026-07-26): the operator typed
 * "vis in ascii emojies" six times, and the throttle silenced four of them.
 * Those four are the operator doing this hook's job by hand because the hook
 * had rate-limited its response to an unambiguous request. Rate-limiting an
 * explicit ask is backwards; the throttle exists for the IMPLICIT set below.
 */
const EXPLICIT_ASK_RE =
  /\b(?:vis(?:ualiz[es]?|ualise)?|ascii|emoji(?:es|s)?|diagram|chart|sketch|draw)\b/i;

/**
 * IMPLICIT shape request: the answer wants structure but the user did not say
 * so. These are throttled, because firing on every "status" would be noise.
 */
const IMPLICIT_SHAPE_RE =
  /\b(?:status|where do we stand|what'?s next|compare|comparison|trade-?offs?|options|breakdown|summar(?:y|ise|ize)|explain|show me|walk me through)\b/i;

/** The user is already routing to a skill — do not second-guess it. */
const ALREADY_ROUTED_RE = /\/(?:ork|hq-ext):[a-z-]+/i;

function counterPath(sessionId: string): string {
  // session_id is untrusted hook input (#1826 class): route it through the
  // same sanitizer the session temp dir uses, so a '../' segment cannot
  // steer this write outside the session storage dir.
  const safe = safeIdentifier(sessionId, 'invalid');
  return join(getSessionStorageDir(), `${safe}-visual-nudge.count`);
}

/**
 * Returns the 1-based re-anchor ordinal when this qualifying prompt should
 * fire, or null when it should stay quiet. Fails CLOSED as null — a counter
 * problem must never turn into per-turn noise.
 */
function fireOrdinal(sessionId: string, explicit: boolean): number | null {
  const path = counterPath(sessionId);
  let seen = 0;
  try {
    if (existsSync(path)) {
      const parsed = Number.parseInt(readFileSync(path, 'utf8').trim(), 10);
      if (Number.isFinite(parsed) && parsed >= 0) seen = parsed;
    }
  } catch {
    return null; // unreadable counter: stay quiet rather than fire every turn
  }

  try {
    mkdirSync(getSessionStorageDir(), { recursive: true });
    writeFileSync(path, String(seen + 1), 'utf8');
  } catch {
    return null; // cannot persist: firing again next turn would be noise
  }

  // An EXPLICIT ask bypasses the throttle entirely. The counter is still
  // advanced above so implicit prompts keep their cadence, but a user who
  // typed "ascii"/"vis" has already made the request and must never be
  // rate-limited into silence.
  if (explicit) return seen + 1;

  // Implicit: fire on the 1st qualifying prompt, then every THROTTLE_EVERY.
  if (seen % THROTTLE_EVERY !== 0) return null;
  return Math.floor(seen / THROTTLE_EVERY) + 1;
}

export function visualStyleNudge(
  input: HookInput,
  _ctx: HookContext = NOOP_CTX,
): HookResult {
  const prompt = typeof input.prompt === 'string' ? input.prompt : '';
  const sessionId = input.session_id || 'unknown-session';

  if (prompt.length < MIN_PROMPT_LENGTH) return outputSilentSuccess();
  if (ALREADY_ROUTED_RE.test(prompt)) return outputSilentSuccess();

  const explicit = EXPLICIT_ASK_RE.test(prompt);
  if (!explicit && !IMPLICIT_SHAPE_RE.test(prompt)) return outputSilentSuccess();

  const ordinal = fireOrdinal(sessionId, explicit);
  if (ordinal === null) return outputSilentSuccess();

  // The ordinal is not decoration: unified-dispatcher runs DELTA DETECTION on
  // the consolidated context and silently drops any turn whose output is
  // byte-identical to the previous one. A constant message would therefore be
  // injected exactly ONCE per session and every later re-anchor would be
  // swallowed — reproducing the decay this hook exists to fix. Verified
  // through the real dispatcher: constant text fired 1/20, the varying text
  // below fires on schedule. Keep this varying.
  return outputPromptContext(
    `[${HOOK_NAME} #${ordinal}] This answer has shape — render it as ASCII art plus ` +
      `semantic emojis (boxes, tables, bar meters), not prose paragraphs. Applies to ` +
      `THIS reply and every later one, not just the first. Full glyph vocabulary and ` +
      `palette: src/rules/visual-style.md. Sub-agents do not inherit this rule; ` +
      `restate it in their prompt if their output reaches the user.`,
  );
}
